/**
 * HUELINE Saturation SS27 — catalogue data (single source of truth).
 * Media files belong in public/hueline/assets/ (and hero-main.* in public/hueline/).
 * Re-skin: replace PALETTE hex values and STYLES entries; keep the same
 * object shape so index.html, product.html, and ui.js keep working.
 */
const HL_PALETTE = {
  Orchid: '#c2378a',
  Cobalt: '#2b3fd6',
  Marigold: '#f0a21a',
  Lagoon: '#13807a',
  Plum: '#3b1f3a',
  Poppy: '#e46d2f',
  Indigo: '#3a4a7a',
  Chalk: '#d9d6cf',
  Ink: '#16141a',
};

/**
 * Re-skin: each style is one row in the shop / wardrobe tabs.
 * code = letter in product id (HL-T-01). tint = accent for UI chrome.
 * items: [name, fabric, price (number), colour name, image keys from ASSETS].
 */
const HL_STYLES = [
  {
    code: 'T',
    label: 'Tailoring',
    tint: '#2b3fd6',
    items: [
      ['Cobalt wrap overcoat', 'Double-faced cashmere', 62000, 'Cobalt', ['look-01']],
      ['Cobalt trouser suit', 'Super 120s wool', 54000, 'Cobalt', ['p-t-02']],
      ['Marigold soft blazer', 'Linen-silk, 210 g/m²', 33500, 'Marigold', ['p-t-03']],
      ['Chalk belted trench', 'Cotton gabardine', 41000, 'Chalk', ['p-t-04']],
    ],
  },
  {
    code: 'S',
    label: 'Streetwear',
    tint: '#13807a',
    items: [
      ['Dyed loop-back hoodie', 'Organic cotton, 420 g/m²', 9800, 'Lagoon', ['mood-street']],
      ['Lagoon fleece set', 'Brushed fleece', 10500, 'Lagoon', ['look-04']],
      ['Orchid boxy tee', 'Combed cotton, 240 g/m²', 4200, 'Orchid', ['p-s-03']],
      ['Poppy cargo trouser', 'Ripstop cotton', 12800, 'Poppy', ['p-s-04']],
    ],
  },
  {
    code: 'E',
    label: 'Evening',
    tint: '#c2378a',
    items: [
      ['Bias-cut slip dress', 'Mulberry silk, 19 momme', 29000, 'Orchid', ['look-02']],
      ['Cobalt column gown', 'Silk crepe de chine', 48000, 'Cobalt', ['p-e-02']],
      ['Orchid halter dress', 'Silk satin', 36500, 'Orchid', ['mood-evening']],
      ['Plum draped midi', 'Silk georgette', 31500, 'Plum', ['p-e-04']],
    ],
  },
  {
    code: 'K',
    label: 'Knitwear',
    tint: '#f0a21a',
    items: [
      ['Marigold cardigan set', 'Lambswool', 16800, 'Marigold', ['look-03']],
      ['Orchid ribbed crewneck', 'Merino, 12 gauge', 14500, 'Orchid', ['p-k-02']],
      ['Lagoon fine-knit polo', 'Cotton-silk', 11200, 'Lagoon', ['p-k-03']],
      ['Chalk cable vest', 'Undyed alpaca', 13900, 'Chalk', ['p-k-04']],
    ],
  },
  {
    code: 'R',
    label: 'Resort',
    tint: '#e46d2f',
    items: [
      ['Block-print shirt dress', 'Hand-block cotton voile', 18500, 'Poppy', ['look-05', 'mood-resort']],
      ['Marigold tiered sundress', 'Cotton mulmul', 15500, 'Marigold', ['p-r-02']],
      ['Lagoon tiered maxi', 'Cotton voile', 17200, 'Lagoon', ['p-r-03']],
      ['Chalk wide-leg set', 'Linen, 180 g/m²', 21000, 'Chalk', ['p-r-04']],
    ],
  },
  {
    code: 'D',
    label: 'Denim',
    tint: '#3a4a7a',
    items: [
      ['Indigo trucker jacket', 'Indigo + cobalt overdye', 17900, 'Indigo', ['look-06']],
      ['Straight selvedge jean', '14 oz selvedge', 14900, 'Indigo', ['mood-denim']],
      ['Rinse wide-leg jean', '12 oz organic denim', 13500, 'Indigo', ['p-d-03']],
      ['Overdyed shirt dress', 'Indigo chambray', 16200, 'Cobalt', ['p-d-04']],
    ],
  },
];

/**
 * Re-skin: only request files listed here (photos). Missing files fall back in UI.
 */
const HL_ASSETS = [
  'look-01',
  'look-02',
  'look-03',
  'look-04',
  'look-05',
  'look-06',
  'mood-street',
  'mood-evening',
  'mood-resort',
  'mood-denim',
  'dye-cobalt',
  'dye-marigold',
  'dye-orchid',
  'dye-lagoon',
  'atelier',
  'p-t-02',
  'p-t-03',
  'p-t-04',
  'p-s-03',
  'p-s-04',
  'p-e-02',
  'p-e-04',
  'p-k-02',
  'p-k-03',
  'p-k-04',
  'p-r-02',
  'p-r-03',
  'p-r-04',
  'p-d-03',
  'p-d-04',
  'hero-poster',
];

/** Close-up hero clips only (under assets/). */
const HL_VIDEOS = ['hero-close-1', 'hero-close-2'];

const HL_DYE_SWATCHES = [
  {
    key: 'cobalt',
    name: 'Cobalt',
    bg: '#2b3fd6',
    fg: '#eceef2',
    ref: 'HL-04/01',
    recipe: 'Indigo vat, 3 dips',
    photo: 'dye-cobalt',
    productCode: 'HL-T-01',
    notes: { Base: 'Indigo vat', Fix: 'Alum mordant', Fastness: 'Grade 4–5 wash' },
  },
  {
    key: 'marigold',
    name: 'Marigold',
    bg: '#f0a21a',
    fg: '#16141a',
    ref: 'HL-04/02',
    recipe: 'Tagetes petals, alum',
    photo: 'dye-marigold',
    productCode: 'HL-K-01',
    notes: { Base: 'Tagetes', Fix: 'Alum', Fastness: 'Grade 3–4 light' },
  },
  {
    key: 'orchid',
    name: 'Orchid',
    bg: '#c2378a',
    fg: '#eceef2',
    ref: 'HL-04/03',
    recipe: 'Lac + madder',
    photo: 'dye-orchid',
    productCode: 'HL-E-01',
    notes: { Base: 'Lac', Fix: 'Copper mordant', Fastness: 'Grade 4 wash' },
  },
  {
    key: 'lagoon',
    name: 'Lagoon',
    bg: '#13807a',
    fg: '#eceef2',
    ref: 'HL-04/04',
    recipe: 'Indigo over pomegranate',
    photo: 'dye-lagoon',
    productCode: 'HL-S-02',
    notes: { Base: 'Pomegranate + indigo', Fix: 'Alum', Fastness: 'Grade 4–5' },
  },
];

const HL_LOOKS = [
  {
    num: '01',
    asset: 'look-01',
    title: 'Cobalt structure',
    copy: 'Double-faced cashmere cut sharp, dyed in three dips until the blue reads almost electric.',
    productCode: 'HL-T-01',
  },
  {
    num: '02',
    asset: 'look-02',
    title: 'Evening orchid',
    copy: 'Bias slip in 19 momme silk — the hem moves like water under Jaipur streetlight.',
    productCode: 'HL-E-01',
  },
  {
    num: '03',
    asset: 'look-03',
    title: 'Marigold knit',
    copy: 'Lambswool cardigan set, marigold from Bagru tagetes, paired with chalk alpaca.',
    productCode: 'HL-K-01',
  },
  {
    num: '04',
    asset: 'look-04',
    title: 'Lagoon fleece',
    copy: 'Brushed loop-back and fleece in lagoon green — streetwear washed in the same vat as tailoring.',
    productCode: 'HL-S-02',
  },
  {
    num: '05',
    asset: 'look-05',
    title: 'Resort block',
    copy: 'Hand-block voile dress; six days per print run, forty-eight pieces then the screen rests.',
    productCode: 'HL-R-01',
  },
  {
    num: '06',
    asset: 'look-06',
    title: 'Indigo denim',
    copy: '14 oz selvedge overdyed cobalt on the trucker — raw edge, saturated seam.',
    productCode: 'HL-D-01',
  },
];

function hlPad(n) {
  return String(n).padStart(2, '0');
}

function hlBuildProducts() {
  const all = [];
  HL_STYLES.forEach((style) => {
    style.items.forEach((item, idx) => {
      const [name, fabric, price, colour, images] = item;
      const code = `HL-${style.code}-${hlPad(idx + 1)}`;
      const views = hlViewsForImages(images);
      all.push({
        code,
        styleCode: style.code,
        styleLabel: style.label,
        styleTint: style.tint,
        name,
        fabric,
        price,
        colour,
        colourHex: HL_PALETTE[colour] || '#6a6773',
        images,
        views,
      });
    });
  });
  return all;
}

/** Full frame + upper / lower detail crops (CSS object-position). */
function hlViewsForImages(images) {
  const main = images[0];
  const list = [{ type: 'full', asset: main, pos: '50% 50%' }];
  list.push({ type: 'detail-upper', asset: main, pos: '50% 18%' });
  list.push({ type: 'detail-lower', asset: main, pos: '50% 82%' });
  if (images[1]) {
    list.push({ type: 'alt', asset: images[1], pos: '50% 50%' });
  }
  return list;
}

const HL_ALL = hlBuildProducts();
const HL_BY_CODE = Object.fromEntries(HL_ALL.map((p) => [p.code, p]));

/**
 * Re-skin: path helper — only ASSETS / VIDEOS / hero-main roots are referenced.
 */
function hlSrc(name, ext) {
  if (name === 'hero-main') {
    return ext === 'poster' ? './assets/hero-poster.jpg' : `./hero-main.${ext || 'webm'}`;
  }
  if (name === 'dye-yard') {
    return `./assets/dye-yard.${ext || 'webm'}`;
  }
  if (HL_VIDEOS.includes(name)) {
    return `./assets/${name}.${ext || 'webm'}`;
  }
  if (HL_ASSETS.includes(name)) {
    if (ext === 'jpg' || !ext) return `./assets/${name}.jpg`;
  }
  return `./assets/${name}.${ext || 'jpg'}`;
}

/** Runtime asset probes (populated on init). */
const HL_LOCAL = {
  _photos: new Set(),
  _videos: new Set(),
  has(name) {
    return this._photos.has(name);
  },
  hasVideo(name) {
    return this._videos.has(name);
  },
  async probe() {
    const photoChecks = HL_ASSETS.map(async (name) => {
      const url = hlSrc(name, 'jpg');
      try {
        const r = await fetch(url, { method: 'HEAD', cache: 'no-store' });
        if (r.ok) this._photos.add(name);
      } catch (_) {
        /* offline or missing */
      }
    });
    const videoNames = [...HL_VIDEOS, 'dye-yard'];
    const videoChecks = videoNames.map(async (name) => {
      for (const ext of ['webm', 'mp4']) {
        const url = hlSrc(name, ext);
        try {
          const r = await fetch(url, { method: 'HEAD', cache: 'no-store' });
          if (r.ok) {
            this._videos.add(name);
            break;
          }
        } catch (_) {
          /* missing */
        }
      }
    });
    const heroChecks = ['webm', 'mp4'].map(async (ext) => {
      try {
        const r = await fetch(hlSrc('hero-main', ext), { method: 'HEAD', cache: 'no-store' });
        if (r.ok) this._videos.add('hero-main');
      } catch (_) {}
    });
    await Promise.all([...photoChecks, ...videoChecks, ...heroChecks]);
  },
};

function hlFormatPrice(n) {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(n);
}

window.HL = {
  PALETTE: HL_PALETTE,
  STYLES: HL_STYLES,
  ASSETS: HL_ASSETS,
  VIDEOS: HL_VIDEOS,
  DYE_SWATCHES: HL_DYE_SWATCHES,
  LOOKS: HL_LOOKS,
  ALL: HL_ALL,
  byCode(code) {
    return HL_BY_CODE[code] || HL_BY_CODE['HL-T-01'];
  },
  src: hlSrc,
  LOCAL: HL_LOCAL,
  formatPrice: hlFormatPrice,
  viewsFor: hlViewsForImages,
};

document.addEventListener('DOMContentLoaded', () => {
  HL_LOCAL.probe();
});

/* HUELINE Saturation SS27 — shared styles (index + product) */

:root {
  --paper: #eceef2;
  --ink: #16141a;
  --mute: #6a6773;
  --line: rgba(22, 20, 26, 0.16);
  --cobalt: #2b3fd6;
  --marigold: #f0a21a;
  --orchid: #c2378a;
  --lagoon: #13807a;
  --f-display: "Bodoni Moda", "Didot", "Bodoni 72", Georgia, serif;
  --f-cond: "Archivo", "Helvetica Neue", Arial, sans-serif;
  --f-sans: Georgia, "Times New Roman", serif;
  --f-mono: "IBM Plex Mono", ui-monospace, monospace;
  --gutter: clamp(16px, 4vw, 56px);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --nav-h: 64px;
  --accent: var(--cobalt);
  --sbg: var(--paper);
  --sfg: var(--ink);
  --cc: var(--cobalt);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: auto;
}

html.lenis,
html.lenis body {
  height: auto;
}

.lenis.lenis-smooth {
  scroll-behavior: auto;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--f-sans);
  font-size: 17px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

body.is-locked {
  overflow: hidden;
}

img,
video {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

:focus-visible {
  outline: 2px solid var(--cobalt);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ——— Typography utilities ——— */
.t-display {
  font-family: var(--f-display);
  font-style: italic;
}

.t-cond {
  font-family: var(--f-cond);
  font-variation-settings: "wdth" 62;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  line-height: 0.95;
}

.t-mono {
  font-family: var(--f-mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.t-price {
  font-family: var(--f-mono);
  font-size: 11px;
  letter-spacing: 0.08em;
}

.mask-line {
  overflow: hidden;
  display: block;
}

.mask-line > span {
  display: block;
  will-change: transform;
}

[data-lines] .w {
  display: inline-block;
  margin-right: 0.28em;
  opacity: 0;
}

/* ——— Custom cursor ——— */
.hl-cursor {
  position: fixed;
  top: 0;
  left: 0;
  width: 12px;
  height: 12px;
  border: 1px solid var(--ink);
  border-radius: 50%;
  pointer-events: none;
  z-index: 9999;
  mix-blend-mode: difference;
  transform: translate(-50%, -50%);
  transition: width 0.25s var(--ease), height 0.25s var(--ease), border-color 0.2s;
}

.hl-cursor-dot {
  position: fixed;
  top: 0;
  left: 0;
  width: 4px;
  height: 4px;
  background: var(--ink);
  border-radius: 50%;
  pointer-events: none;
  z-index: 10000;
  transform: translate(-50%, -50%);
}

.hl-cursor.is-big {
  width: 44px;
  height: 44px;
  border-color: var(--cc, var(--ink));
}

.hl-cursor-label {
  position: fixed;
  top: 0;
  left: 0;
  font-family: var(--f-mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  pointer-events: none;
  z-index: 10001;
  transform: translate(-50%, -50%);
  opacity: 0;
  transition: opacity 0.2s;
}

.hl-cursor-label.is-on {
  opacity: 1;
}

@media (hover: none), (pointer: coarse) {
  .hl-cursor,
  .hl-cursor-dot,
  .hl-cursor-label {
    display: none !important;
  }
}

/* ——— Nav ——— */
.hl-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 900;
  height: var(--nav-h);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--gutter);
  transition: background 0.45s var(--ease), border-color 0.45s;
  border-bottom: 1px solid transparent;
}

.hl-nav.is-solid {
  background: var(--paper);
  border-bottom-color: var(--line);
}

.hl-nav.is-hero {
  color: #fff;
  mix-blend-mode: difference;
}

.hl-nav.is-hero.is-solid {
  mix-blend-mode: normal;
  color: var(--ink);
}

.hl-wordmark {
  font-size: clamp(1.1rem, 2.5vw, 1.35rem);
  display: flex;
  align-items: baseline;
  gap: 0.05em;
}

.hl-wordmark .hue {
  font-family: var(--f-cond);
  font-variation-settings: "wdth" 62;
  letter-spacing: 0.08em;
}

.hl-wordmark .line {
  font-family: var(--f-display);
  font-style: italic;
}

.hl-nav-links {
  display: none;
  gap: 1.75rem;
}

.hl-nav-links a {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.hl-nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.hl-nav-btn {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.35rem 0.5rem;
  position: relative;
}

.hl-nav-btn .badge {
  position: absolute;
  top: -2px;
  right: -2px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--orchid);
  color: #fff;
  font-size: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hl-menu-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
}

.hl-menu-toggle span {
  display: block;
  height: 1px;
  background: currentColor;
  transition: transform 0.3s var(--ease);
}

@media (min-width: 900px) {
  .hl-nav-links {
    display: flex;
  }
  .hl-menu-toggle {
    display: none;
  }
}

/* ——— Loader ——— */
.hl-loader {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  pointer-events: none;
}

.hl-loader-band {
  background: var(--band, var(--cobalt));
  transform-origin: bottom center;
  transform: scaleY(0);
}

.hl-loader-ui {
  position: fixed;
  inset: 0;
  z-index: 2001;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.hl-loader-count {
  font-family: var(--f-mono);
  font-size: clamp(2rem, 8vw, 4rem);
  letter-spacing: 0.2em;
  color: #fff;
  mix-blend-mode: difference;
}

/* ——— Hero ——— */
.hl-hero {
  position: relative;
  height: 100svh;
  overflow: hidden;
}

.hl-hero-pin {
  height: 100svh;
  position: relative;
}

.hl-hero-ground {
  position: absolute;
  inset: 0;
  background: var(--paper);
  opacity: 0;
  z-index: 0;
}

.hl-hero-media {
  position: absolute;
  inset: 0;
  z-index: 1;
  overflow: hidden;
  clip-path: inset(18% 26% round 6px);
  transform: scale(1.08);
}

.hl-hero-media video,
.hl-hero-fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hl-hero-fallback {
  display: none;
  position: absolute;
  inset: 0;
  background: linear-gradient(145deg, var(--cobalt), var(--orchid));
}

.hl-hero-content {
  position: relative;
  z-index: 3;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: calc(var(--nav-h) + 24px) var(--gutter) var(--gutter);
  color: #fff;
  text-shadow: 0 1px 24px rgba(0, 0, 0, 0.35);
}

.hl-hero-eyebrow {
  margin-bottom: 1.5rem;
  opacity: 0;
}

.hl-hero-title {
  font-size: clamp(2.4rem, 11vw, 7rem);
  margin: 0;
}

.hl-hero-title .char {
  display: inline-block;
  opacity: 0;
}

.hl-hero-title .colour {
  font-family: var(--f-display);
  font-style: italic;
  color: var(--marigold);
  text-transform: lowercase;
  font-size: 1.05em;
}

.hl-hero-foot {
  margin-top: auto;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 1.5rem;
  align-items: end;
  opacity: 0;
}

.hl-hero-copy {
  max-width: 28ch;
  font-size: 0.95rem;
  line-height: 1.5;
}

.hl-hero-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1.25rem;
}

.hl-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: transform 0.35s var(--ease);
}

.hl-scroll-cue {
  writing-mode: vertical-rl;
  font-family: var(--f-mono);
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  opacity: 0.7;
}

.hl-hero-closeups {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}

.hl-hero-pane {
  position: absolute;
  width: min(28vw, 220px);
  aspect-ratio: 3/4;
  bottom: 12%;
  overflow: hidden;
  border-radius: 8px;
  box-shadow: 0 24px 60px rgba(22, 20, 26, 0.25);
  opacity: 0;
  transform: translateY(40px);
}

.hl-hero-pane.is-left {
  left: 6%;
  transform: rotate(-5deg) translateY(40px);
}

.hl-hero-pane.is-right {
  right: 6%;
  transform: rotate(5deg) translateY(40px);
}

.hl-hero-pane video,
.hl-hero-pane .hl-media-fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hl-hero-pane .hl-media-fallback {
  display: none;
  position: absolute;
  inset: 0;
}

.hl-hero-arch-note {
  position: absolute;
  bottom: 8%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 4;
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0;
  text-align: center;
  color: var(--ink);
}

/* ——— Ticker ——— */
.hl-ticker-wrap {
  overflow: hidden;
  border-block: 1px solid var(--line);
  padding: 0.85rem 0;
  background: var(--paper);
}

.hl-ticker {
  display: flex;
  width: max-content;
  animation: hl-ticker 40s linear infinite;
}

.hl-ticker span {
  font-family: var(--f-cond);
  font-variation-settings: "wdth" 75;
  font-size: clamp(0.75rem, 2vw, 0.95rem);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 0 1.5rem;
  white-space: nowrap;
}

.hl-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--dot, var(--orchid));
  margin: 0 0.75rem;
  vertical-align: middle;
}

@keyframes hl-ticker {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* ——— Section shell ——— */
.hl-section {
  padding: clamp(3rem, 10vw, 7rem) var(--gutter);
}

.hl-section-head {
  max-width: 18ch;
  margin-bottom: clamp(2rem, 5vw, 3.5rem);
}

.hl-section-head h2 {
  font-family: var(--f-cond);
  font-variation-settings: "wdth" 70;
  font-size: clamp(1.75rem, 5vw, 3rem);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 0 0 0.75rem;
  font-weight: 600;
}

.hl-section-head h2 em {
  font-family: var(--f-display);
  font-style: italic;
  text-transform: none;
  letter-spacing: 0;
}

/* ——— Arches gallery ——— */
.hl-arches {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: clamp(8px, 1.5vw, 16px);
}

.hl-arch {
  position: relative;
  aspect-ratio: 3/5;
  border-radius: 200px 200px 6px 6px;
  overflow: hidden;
  clip-path: inset(100% 0 0 0);
}

.hl-arch img,
.hl-arch .hl-media-fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scale(1.4);
}

.hl-arch-cap {
  position: absolute;
  inset: auto 0 0;
  padding: 1rem;
  background: linear-gradient(transparent, rgba(22, 20, 26, 0.65));
  color: #fff;
}

.hl-arch-cap .t-mono {
  color: rgba(255, 255, 255, 0.85);
}

@media (max-width: 1100px) {
  .hl-arches {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 700px) {
  .hl-arches {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ——— Wardrobe ring ——— */
.hl-wardrobe {
  position: relative;
  min-height: 520px;
}

.hl-wardrobe-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.hl-wardrobe-tab {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.45rem 0.85rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  transition: background 0.3s, color 0.3s;
}

.hl-wardrobe-tab.is-active {
  background: var(--tab, var(--ink));
  color: #fff;
  border-color: transparent;
}

.hl-wardrobe-stage {
  perspective: 1200px;
  height: 420px;
  position: relative;
  touch-action: none;
  cursor: grab;
}

.hl-wardrobe-stage.is-dragging {
  cursor: grabbing;
}

.hl-wardrobe-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  transform-style: preserve-3d;
  will-change: transform;
}

.hl-wardrobe-card {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(120px, 16vw, 168px);
  margin-left: calc(clamp(120px, 16vw, 168px) / -2);
  margin-top: -200px;
  transform-style: preserve-3d;
  backface-visibility: hidden;
  transition: opacity 0.15s;
}

.hl-wardrobe-card-inner {
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(22, 20, 26, 0.12);
  background: var(--paper);
}

.hl-wardrobe-card img,
.hl-wardrobe-card .hl-media-fallback {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
}

.hl-wardrobe-cap {
  margin-top: 1.25rem;
  min-height: 5rem;
  border-top: 1px solid var(--line);
  padding-top: 1rem;
}

.hl-wardrobe-cap .t-mono {
  color: var(--mute);
}

@media (max-width: 700px) {
  .hl-wardrobe-card {
    width: 100px;
    margin-left: -50px;
  }
  .hl-wardrobe-stage {
    height: 360px;
  }
}

/* ——— Style rails ——— */
.hl-rails {
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

.hl-rail-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.75rem;
}

.hl-rail-track-wrap {
  overflow: hidden;
  margin-inline: calc(var(--gutter) * -1);
  padding-inline: var(--gutter);
}

.hl-rail-track {
  display: flex;
  gap: 1rem;
  width: max-content;
  cursor: grab;
  touch-action: pan-y;
}

.hl-rail-track.is-dragging {
  cursor: grabbing;
}

/* ——— Product card ——— */
.hl-card {
  flex: 0 0 clamp(200px, 22vw, 260px);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  background: var(--paper);
  text-align: left;
  transition: border-color 0.3s;
}

.hl-card:hover {
  border-color: rgba(22, 20, 26, 0.28);
}

.hl-card-media {
  position: relative;
  aspect-ratio: 3/4;
  overflow: hidden;
}

.hl-card-media img,
.hl-card-media .hl-media-fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.45s var(--ease);
}

.hl-card-media .hl-card-hover {
  position: absolute;
  inset: 0;
  opacity: 0;
}

.hl-card:hover .hl-card-hover {
  opacity: 1;
}

.hl-card-body {
  padding: 0.85rem 1rem 1rem;
}

.hl-card-name {
  font-family: var(--f-cond);
  font-size: 0.85rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin: 0 0 0.25rem;
}

.hl-card-fabric {
  font-size: 0.8rem;
  color: var(--mute);
  margin: 0 0 0.5rem;
}

.hl-card-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.hl-dye-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--dot, var(--cobalt));
  border: 1px solid rgba(22, 20, 26, 0.12);
}

/* ——— Lookbook horizontal ——— */
.hl-lookbook-pin {
  height: 100vh;
  overflow: hidden;
}

.hl-lookbook-track {
  display: flex;
  height: 100%;
  width: max-content;
}

.hl-look-panel {
  width: 100vw;
  height: 100%;
  flex-shrink: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--gutter);
  padding: calc(var(--nav-h) + 2rem) var(--gutter) var(--gutter);
  align-items: center;
}

.hl-look-num {
  font-family: var(--f-display);
  font-style: italic;
  font-size: clamp(4rem, 15vw, 9rem);
  line-height: 0.85;
  margin: 0;
  color: var(--mute);
}

.hl-look-frame {
  clip-path: inset(0 100% 0 0);
  border-radius: 12px;
  overflow: hidden;
}

.hl-look-frame img,
.hl-look-frame .hl-media-fallback {
  width: 100%;
  aspect-ratio: 4/5;
  object-fit: cover;
  transform: scale(1.35);
}

@media (max-width: 700px) {
  .hl-lookbook-pin {
    height: auto;
  }
  .hl-lookbook-track {
    flex-direction: column;
    width: 100%;
  }
  .hl-look-panel {
    width: 100%;
    grid-template-columns: 1fr;
    min-height: auto;
    padding-block: 3rem;
  }
}

/* ——— Colour story ——— */
.hl-colour-story {
  transition: background 0.6s var(--ease), color 0.6s var(--ease);
  background: var(--sbg);
  color: var(--sfg);
}

.hl-colour-sticky {
  position: sticky;
  top: var(--nav-h);
  padding-block: 2rem;
  z-index: 2;
  pointer-events: none;
}

.hl-colour-roll {
  overflow: hidden;
  height: clamp(2.5rem, 8vw, 4.5rem);
}

.hl-colour-roll-inner {
  font-family: var(--f-display);
  font-style: italic;
  font-size: clamp(2.5rem, 10vw, 5rem);
  line-height: 1;
  will-change: transform;
}

.hl-colour-recipe {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  margin-top: 0.5rem;
  opacity: 0.85;
}

.hl-swatches {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.hl-swatch {
  min-height: 420px;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.hl-swatch-photo {
  flex: 1;
  border-radius: 8px;
  overflow: hidden;
  min-height: 140px;
}

.hl-swatch-photo img,
.hl-swatch-photo .hl-media-fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
  min-height: 140px;
}

.hl-swatch-notes {
  font-size: 0.75rem;
  opacity: 0.9;
  line-height: 1.45;
}

@media (max-width: 900px) {
  .hl-swatches {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 700px) {
  .hl-swatches {
    grid-template-columns: 1fr;
  }
}

/* ——— Shop grid ——— */
.hl-shop-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}

.hl-shop-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.hl-shop-tab {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.4rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: 999px;
}

.hl-shop-tab.is-active {
  background: var(--ink);
  color: var(--paper);
}

.hl-shop-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.hl-shop-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  position: relative;
}

.hl-shop-grid .hl-card {
  flex: none;
  width: 100%;
}

@media (max-width: 1100px) {
  .hl-shop-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 700px) {
  .hl-shop-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ——— Film band ——— */
.hl-film-band {
  padding: clamp(2rem, 6vw, 4rem) var(--gutter);
}

.hl-film-frame {
  clip-path: inset(0 6% round 28px);
  border-radius: 18px;
  overflow: hidden;
  transform: scale(1.18);
}

.hl-film-frame {
  position: relative;
}

.hl-film-frame video,
.hl-film-frame .hl-media-fallback {
  width: 100%;
  aspect-ratio: 21/9;
  object-fit: cover;
}

.hl-film-frame .hl-media-fallback {
  display: none;
  position: absolute;
  inset: 0;
}

/* ——— Atelier ——— */
.hl-atelier-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: var(--gutter);
  align-items: end;
}

.hl-atelier-photo {
  clip-path: inset(100% 0 0 0);
  border-radius: 12px;
  overflow: hidden;
}

.hl-atelier-photo img,
.hl-atelier-photo .hl-media-fallback {
  width: 100%;
  aspect-ratio: 4/5;
  object-fit: cover;
}

.hl-stats {
  display: grid;
  gap: 1.5rem;
}

.hl-stat-num {
  font-family: var(--f-display);
  font-style: italic;
  font-size: clamp(2.5rem, 6vw, 4rem);
  line-height: 1;
}

.hl-stat-label {
  font-size: 0.95rem;
  color: var(--mute);
  max-width: 28ch;
}

@media (max-width: 800px) {
  .hl-atelier-grid {
    grid-template-columns: 1fr;
  }
}

/* ——— Footer ——— */
.hl-footer {
  border-top: 1px solid var(--line);
  padding: clamp(3rem, 8vw, 5rem) var(--gutter) 2rem;
}

.hl-footer-top {
  display: grid;
  grid-template-columns: 1.2fr repeat(3, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}

.hl-footer-mark {
  font-size: clamp(2rem, 6vw, 3.5rem);
}

.hl-footer-col h3 {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin: 0 0 1rem;
}

.hl-footer-col ul {
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: 0.9rem;
}

.hl-footer-col li + li {
  margin-top: 0.45rem;
}

.hl-newsletter {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.hl-newsletter input {
  flex: 1;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 0.55rem 1rem;
  background: transparent;
}

.hl-newsletter button {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.55rem 1rem;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
}

.hl-footer-small {
  font-family: var(--f-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--mute);
  border-top: 1px solid var(--line);
  padding-top: 1.5rem;
}

@media (max-width: 800px) {
  .hl-footer-top {
    grid-template-columns: 1fr 1fr;
  }
}

/* ——— Media fallback ——— */
.hl-media-fallback {
  background: var(--fb, var(--cobalt));
  display: flex;
  align-items: flex-end;
  padding: 0.75rem;
  color: rgba(255, 255, 255, 0.85);
  font-family: var(--f-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* ——— Overlays ——— */
.hl-overlay {
  position: fixed;
  inset: 0;
  z-index: 1100;
  background: rgba(22, 20, 26, 0.45);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s var(--ease), visibility 0.35s;
}

.hl-overlay.is-open {
  opacity: 1;
  visibility: visible;
}

.hl-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: min(420px, 100%);
  height: 100%;
  z-index: 1200;
  background: var(--paper);
  border-left: 1px solid var(--line);
  transform: translateX(100%);
  transition: transform 0.45s var(--ease);
  display: flex;
  flex-direction: column;
}

.hl-drawer.is-open {
  transform: translateX(0);
}

.hl-drawer-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem var(--gutter);
  border-bottom: 1px solid var(--line);
}

.hl-drawer-tabs {
  display: flex;
  gap: 1rem;
}

.hl-drawer-tab {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.45;
}

.hl-drawer-tab.is-active {
  opacity: 1;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.hl-drawer-body {
  flex: 1;
  overflow: auto;
  padding: 1rem var(--gutter) 2rem;
}

.hl-drawer-item {
  display: grid;
  grid-template-columns: 72px 1fr auto;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--line);
  align-items: center;
}

.hl-drawer-item .hl-media-fallback,
.hl-drawer-item img {
  width: 72px;
  aspect-ratio: 3/4;
  object-fit: cover;
  border-radius: 6px;
}

.hl-mobile-menu {
  position: fixed;
  inset: 0;
  z-index: 1050;
  background: var(--paper);
  padding: calc(var(--nav-h) + 1rem) var(--gutter);
  transform: translateY(-100%);
  transition: transform 0.45s var(--ease);
}

.hl-mobile-menu.is-open {
  transform: translateY(0);
}

.hl-mobile-menu nav {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  font-family: var(--f-cond);
  font-size: 1.5rem;
  text-transform: uppercase;
}

.hl-search-panel {
  position: fixed;
  inset: 0;
  z-index: 1150;
  background: var(--paper);
  padding: calc(var(--nav-h) + 1rem) var(--gutter);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s, visibility 0.35s;
}

.hl-search-panel.is-open {
  opacity: 1;
  visibility: visible;
}

.hl-search-input {
  width: 100%;
  border: none;
  border-bottom: 1px solid var(--ink);
  font-family: var(--f-display);
  font-style: italic;
  font-size: clamp(1.5rem, 5vw, 2.5rem);
  padding: 0.5rem 0;
  background: transparent;
}

.hl-search-results {
  margin-top: 2rem;
  display: grid;
  gap: 0.75rem;
  max-height: 60vh;
  overflow: auto;
}

.hl-qv {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) scale(0.96);
  z-index: 1250;
  width: min(920px, calc(100% - 2rem));
  max-height: calc(100vh - 2rem);
  overflow: auto;
  background: var(--paper);
  border-radius: 16px;
  border: 1px solid var(--line);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s, transform 0.35s var(--ease), visibility 0.35s;
}

.hl-qv.is-open {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, -50%) scale(1);
}

.hl-qv-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}

.hl-qv-close {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 2;
  font-family: var(--f-mono);
  font-size: 10px;
}

@media (max-width: 700px) {
  .hl-qv-grid {
    grid-template-columns: 1fr;
  }
}

.hl-toast {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%) translateY(120%);
  z-index: 1300;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.75rem 1.25rem;
  border-radius: 999px;
  transition: transform 0.45s var(--ease);
}

.hl-toast.is-show {
  transform: translateX(-50%) translateY(0);
}

/* ——— Product page ——— */
.hl-pdp {
  padding-top: calc(var(--nav-h) + 1.5rem);
}

.hl-pdp-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: var(--gutter);
  padding: 0 var(--gutter) 3rem;
}

.hl-pdp-gallery {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 1rem;
  position: sticky;
  top: calc(var(--nav-h) + 1rem);
  align-self: start;
}

.hl-pdp-thumbs {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.hl-pdp-thumb {
  border: 1px solid var(--line);
  border-radius: 6px;
  overflow: hidden;
  opacity: 0.55;
  padding: 0;
}

.hl-pdp-thumb.is-active {
  opacity: 1;
  border-color: var(--ink);
}

.hl-pdp-thumb img,
.hl-pdp-thumb .hl-media-fallback {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
}

.hl-pdp-main {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  cursor: zoom-in;
}

.hl-pdp-main img,
.hl-pdp-main .hl-media-fallback {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
  transition: transform 0.15s linear;
}

.hl-pdp-main.is-zoom img {
  transform: scale(1.8);
  transform-origin: var(--zx, 50%) var(--zy, 50%);
}

.hl-pdp-buy h1 {
  font-family: var(--f-cond);
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  text-transform: uppercase;
  margin: 0.5rem 0;
}

.hl-swatches-row {
  display: flex;
  gap: 0.5rem;
  margin: 1rem 0;
}

.hl-size-chip {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  padding: 0.45rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.hl-size-chip.is-active {
  background: var(--ink);
  color: var(--paper);
}

.hl-size-chart {
  font-size: 0.85rem;
  color: var(--mute);
  margin: 0.75rem 0 1.25rem;
}

.hl-pdp-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin: 1.25rem 0;
}

.hl-btn-primary {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.85rem 1.5rem;
  background: var(--ink);
  color: var(--paper);
  border-radius: 999px;
}

.hl-btn-ghost {
  font-family: var(--f-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.85rem 1.25rem;
  border: 1px solid var(--line);
  border-radius: 999px;
}

.hl-pincode {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
}

.hl-pincode input {
  width: 120px;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.5rem 0.65rem;
  font-family: var(--f-mono);
  letter-spacing: 0.1em;
}

.hl-pincode-result {
  margin-top: 0.65rem;
  font-size: 0.9rem;
}

.hl-pdp-details {
  margin-top: 2rem;
  font-size: 0.9rem;
  color: var(--mute);
}

.hl-related {
  padding: 3rem var(--gutter) 4rem;
  border-top: 1px solid var(--line);
}

.hl-related-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin-top: 1.5rem;
}

@media (max-width: 900px) {
  .hl-pdp-grid {
    grid-template-columns: 1fr;
  }
  .hl-pdp-gallery {
    position: relative;
    top: 0;
  }
  .hl-related-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ——— Reduced motion ——— */
@media (prefers-reduced-motion: reduce) {
  .hl-loader {
    display: none !important;
  }
  .hl-ticker {
    animation: none;
  }
  .hl-hero-media {
    clip-path: none !important;
    transform: none !important;
  }
  .hl-film-frame {
    clip-path: inset(0 0 round 18px) !important;
    transform: none !important;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/**
 * HUELINE — shared UI (Lenis, nav, commerce, overlays, media fallbacks).
 */
(function () {
  'use strict';

  const REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const STORAGE_BAG = 'hl_bag_v1';
  const STORAGE_SAVED = 'hl_saved_v1';
  const STORAGE_PIN = 'hl_pincode_v1';

  let lenis = null;
  let overlayStack = [];
  let lastFocus = null;

  function $(sel, root) {
    return (root || document).querySelector(sel);
  }
  function $$(sel, root) {
    return Array.from((root || document).querySelectorAll(sel));
  }

  function lockScroll(on) {
    document.body.classList.toggle('is-locked', on);
    if (lenis) {
      if (on) lenis.stop();
      else lenis.start();
    }
  }

  function openOverlay(id) {
    const el = document.getElementById(id);
    if (!el) return;
    lastFocus = document.activeElement;
    el.classList.add('is-open');
    el.setAttribute('aria-hidden', 'false');
    overlayStack.push(id);
    lockScroll(true);
    const focusable = el.querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
    if (focusable) focusable.focus();
  }

  function closeOverlay(id) {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove('is-open');
    el.setAttribute('aria-hidden', 'true');
    overlayStack = overlayStack.filter((x) => x !== id);
    if (!overlayStack.length) lockScroll(false);
    if (lastFocus && typeof lastFocus.focus === 'function') lastFocus.focus();
  }

  function closeTopOverlay() {
    const id = overlayStack[overlayStack.length - 1];
    if (id) closeOverlay(id);
  }

  /* ——— Storage ——— */
  function readJSON(key, fallback) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  }

  function writeJSON(key, val) {
    localStorage.setItem(key, JSON.stringify(val));
  }

  function getBag() {
    return readJSON(STORAGE_BAG, []);
  }
  function setBag(items) {
    writeJSON(STORAGE_BAG, items);
    updateBadges();
    renderDrawerPanel('bag');
  }

  function getSaved() {
    return readJSON(STORAGE_SAVED, []);
  }
  function setSaved(items) {
    writeJSON(STORAGE_SAVED, items);
    updateBadges();
    renderDrawerPanel('saved');
  }

  function updateBadges() {
    const bag = getBag();
    const saved = getSaved();
    const bagEl = $('[data-badge="bag"]');
    const savedEl = $('[data-badge="saved"]');
    if (bagEl) {
      bagEl.textContent = bag.length ? String(bag.length) : '';
      bagEl.hidden = !bag.length;
    }
    if (savedEl) {
      savedEl.textContent = saved.length ? String(saved.length) : '';
      savedEl.hidden = !saved.length;
    }
  }

  function addToBag(product, size) {
    const bag = getBag();
    bag.push({
      code: product.code,
      size: size || 'M',
      ts: Date.now(),
    });
    setBag(bag);
  }

  function toggleSaved(product) {
    let saved = getSaved();
    const i = saved.indexOf(product.code);
    if (i >= 0) saved.splice(i, 1);
    else saved.push(product.code);
    setSaved(saved);
  }

  function isSaved(code) {
    return getSaved().includes(code);
  }

  /* ——— Media ——— */
  function dyeHex(colour) {
    return (window.HL && HL.PALETTE[colour]) || '#6a6773';
  }

  function mediaImg(asset, product, alt, className) {
    const wrap = document.createElement('div');
    wrap.className = className || 'hl-media-wrap';
    const img = document.createElement('img');
    img.alt = alt || '';
    img.loading = 'lazy';
    img.decoding = 'async';
    const fb = document.createElement('div');
    fb.className = 'hl-media-fallback';
    fb.style.setProperty('--fb', product ? dyeHex(product.colour) : '#2b3fd6');
    fb.textContent = product ? product.colour : 'Hueline';
    fb.hidden = true;

    const tryAsset = asset || (product && product.images && product.images[0]);
    if (tryAsset && HL.ASSETS.includes(tryAsset)) {
      img.src = HL.src(tryAsset, 'jpg');
      img.onerror = () => {
        img.hidden = true;
        fb.hidden = false;
      };
    } else {
      img.hidden = true;
      fb.hidden = false;
      fb.style.setProperty('--fb', product ? dyeHex(product.colour) : '#2b3fd6');
    }
    wrap.appendChild(img);
    wrap.appendChild(fb);
    return wrap;
  }

  function fillMediaSlot(slot, asset, product, alt) {
    slot.innerHTML = '';
    const node = mediaImg(asset, product, alt);
    slot.appendChild(node.firstChild.tagName === 'IMG' ? node.firstChild : node);
    if (node.children.length > 1) slot.appendChild(node.lastChild);
  }

  function cardElement(product) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'hl-card';
    btn.dataset.product = product.code;
    btn.style.setProperty('--cc', product.colourHex);
    btn.setAttribute('data-cursor', 'color');

    const media = document.createElement('div');
    media.className = 'hl-card-media';
    const mainWrap = mediaImg(product.images[0], product, product.name);
    while (mainWrap.firstChild) media.appendChild(mainWrap.firstChild);

    const hover = document.createElement('div');
    hover.className = 'hl-card-hover';
    const v2 = product.views[1] || product.views[0];
    if (v2 && HL.ASSETS.includes(v2.asset)) {
      const hImg = document.createElement('img');
      hImg.alt = '';
      hImg.src = HL.src(v2.asset, 'jpg');
      hImg.style.objectPosition = v2.pos;
      hImg.onerror = () => {
        const f = document.createElement('div');
        f.className = 'hl-media-fallback';
        f.style.setProperty('--fb', product.colourHex);
        hImg.replaceWith(f);
      };
      hover.appendChild(hImg);
    } else {
      const f = document.createElement('div');
      f.className = 'hl-media-fallback';
      f.style.setProperty('--fb', product.colourHex);
      hover.appendChild(f);
    }
    media.appendChild(hover);

    const body = document.createElement('div');
    body.className = 'hl-card-body';
    body.innerHTML = `<p class="hl-card-name">${product.name}</p>
      <p class="hl-card-fabric">${product.fabric}</p>
      <div class="hl-card-meta"><span class="t-price">${HL.formatPrice(product.price)}</span>
      <span class="hl-dye-dot" style="--dot:${product.colourHex}"></span></div>`;

    btn.append(media, body);
    return btn;
  }

  /* ——— Toast ——— */
  function toast(msg) {
    let el = $('#hl-toast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'hl-toast';
      el.className = 'hl-toast';
      el.setAttribute('role', 'status');
      document.body.appendChild(el);
    }
    el.textContent = msg;
    el.classList.add('is-show');
    clearTimeout(el._t);
    el._t = setTimeout(() => el.classList.remove('is-show'), 2800);
  }

  /* ——— Footer ——— */
  function buildFooter() {
    const mount = $('#hl-footer-mount');
    if (!mount) return;
    mount.innerHTML = `<footer class="hl-footer" id="shop">
      <div class="hl-footer-top">
        <div>
          <p class="hl-footer-mark t-cond">HUE<span class="t-display" style="font-size:.85em">line</span></p>
          <p style="max-width:32ch;color:var(--mute);font-size:.95rem;margin-top:1rem">Saturation SS27 — womenswear dyed by hand in Bagru, cut in Jaipur.</p>
        </div>
        <div class="hl-footer-col"><h3>Explore</h3><ul>
          <li><a href="#wardrobe">Wardrobe</a></li>
          <li><a href="#lookbook">Lookbook</a></li>
          <li><a href="#colour">Colour</a></li>
          <li><a href="#shop-grid">Shop</a></li>
        </ul></div>
        <div class="hl-footer-col"><h3>Help</h3><ul>
          <li><a href="#" data-action="size-chart">Size chart</a></li>
          <li><a href="#">Shipping</a></li>
          <li><a href="#">Returns</a></li>
        </ul></div>
        <div class="hl-footer-col"><h3>Newsletter</h3>
          <p style="font-size:.9rem;color:var(--mute)">Drop notes — no spam, only colour.</p>
          <form class="hl-newsletter" id="hl-newsletter"><input type="email" placeholder="Email" aria-label="Email" required />
          <button type="submit">Join</button></form>
        </div>
      </div>
      <p class="hl-footer-small">© Hueline Studio · SS27 Saturation · Crafted without a build step</p>
    </footer>`;
    $('#hl-newsletter')?.addEventListener('submit', (e) => {
      e.preventDefault();
      toast('Welcome to the dye list');
      e.target.reset();
    });
  }

  /* ——— Nav ——— */
  function initNav() {
    const nav = $('.hl-nav');
    if (!nav) return;
    const hero = $('.hl-hero');
    if (hero) nav.classList.add('is-hero');

    const onScroll = () => {
      const y = window.scrollY || document.documentElement.scrollTop;
      nav.classList.toggle('is-solid', y > 80);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });

    $('[data-action="search"]')?.addEventListener('click', () => openOverlay('hl-search'));
    $('[data-action="bag"]')?.addEventListener('click', () => openOverlay('hl-drawer'));
    $('[data-action="saved"]')?.addEventListener('click', () => {
      openOverlay('hl-drawer');
      setDrawerTab('saved');
    });
    $('[data-action="menu"]')?.addEventListener('click', () => openOverlay('hl-mobile-menu'));
    $$('.hl-nav-links a[href^="#"]').forEach((a) => {
      a.addEventListener('click', (e) => {
        const id = a.getAttribute('href').slice(1);
        const target = document.getElementById(id);
        if (target) {
          e.preventDefault();
          if (lenis) lenis.scrollTo(target, { offset: -64 });
          else target.scrollIntoView({ behavior: 'smooth' });
          closeOverlay('hl-mobile-menu');
        }
      });
    });
  }

  /* ——— Drawer ——— */
  function setDrawerTab(tab) {
    $$('.hl-drawer-tab').forEach((t) => t.classList.toggle('is-active', t.dataset.tab === tab));
    $$('[data-drawer-panel]').forEach((p) => {
      p.hidden = p.dataset.drawerPanel !== tab;
    });
  }

  function renderDrawerPanel(which) {
    const panel = $(`[data-drawer-panel="${which}"]`);
    if (!panel) return;
    panel.innerHTML = '';
    const codes = which === 'bag' ? getBag().map((x) => x.code) : getSaved();
    if (!codes.length) {
      panel.innerHTML = `<p class="t-mono" style="color:var(--mute)">${which === 'bag' ? 'Your bag is empty' : 'Nothing saved yet'}</p>`;
      return;
    }
    const list = which === 'bag' ? getBag() : getSaved().map((c) => ({ code: c, size: 'M' }));
    list.forEach((entry) => {
      const p = HL.byCode(entry.code);
      const row = document.createElement('div');
      row.className = 'hl-drawer-item';
      const thumb = mediaImg(p.images[0], p, p.name);
      row.appendChild(thumb);
      const meta = document.createElement('div');
      meta.innerHTML = `<p class="t-mono">${p.styleLabel} · ${p.colour}</p><p>${p.name}</p><p class="t-price">${HL.formatPrice(p.price)}</p>`;
      row.appendChild(meta);
      const link = document.createElement('a');
      link.href = `product.html?code=${encodeURIComponent(p.code)}`;
      link.className = 't-mono';
      link.textContent = 'View';
      row.appendChild(link);
      panel.appendChild(row);
    });
  }

  function initDrawer() {
    $$('.hl-drawer-tab').forEach((tab) => {
      tab.addEventListener('click', () => setDrawerTab(tab.dataset.tab));
    });
    $('[data-close="drawer"]')?.addEventListener('click', () => closeOverlay('hl-drawer'));
    renderDrawerPanel('bag');
    renderDrawerPanel('saved');
  }

  /* ——— Search ——— */
  function initSearch() {
    const input = $('#hl-search-input');
    const results = $('#hl-search-results');
    if (!input || !results) return;
    input.addEventListener('input', () => {
      const q = input.value.trim().toLowerCase();
      results.innerHTML = '';
      if (!q) return;
      HL.ALL.filter(
        (p) =>
          p.name.toLowerCase().includes(q) ||
          p.fabric.toLowerCase().includes(q) ||
          p.colour.toLowerCase().includes(q) ||
          p.code.toLowerCase().includes(q)
      )
        .slice(0, 12)
        .forEach((p) => {
          const a = document.createElement('a');
          a.href = `product.html?code=${encodeURIComponent(p.code)}`;
          a.className = 't-mono';
          a.textContent = `${p.code} — ${p.name}`;
          results.appendChild(a);
        });
    });
    $('[data-close="search"]')?.addEventListener('click', () => closeOverlay('hl-search'));
  }

  /* ——— Quick view ——— */
  function openQuickView(code) {
    const p = HL.byCode(code);
    const qv = $('#hl-qv');
    if (!qv || !p) return;
    $('#hl-qv-body').innerHTML = '';
    const grid = document.createElement('div');
    grid.className = 'hl-qv-grid';
    const left = document.createElement('div');
    left.appendChild(mediaImg(p.images[0], p, p.name));
    const right = document.createElement('div');
    right.style.padding = 'clamp(1.25rem,4vw,2rem)';
    right.innerHTML = `<p class="t-mono">${p.styleLabel} · ${p.colour}</p>
      <h2 class="t-cond" style="font-size:1.5rem;margin:.35rem 0">${p.name}</h2>
      <p style="color:var(--mute)">${p.fabric}</p>
      <p class="t-price" style="margin:1rem 0">${HL.formatPrice(p.price)}</p>
      <div class="hl-pdp-actions">
        <button type="button" class="hl-btn-primary" data-qv-bag>Add to bag</button>
        <a class="hl-btn-ghost" href="product.html?code=${encodeURIComponent(p.code)}">Full details</a>
      </div>`;
    grid.append(left, right);
    $('#hl-qv-body').appendChild(grid);
    $('[data-qv-bag]', qv)?.addEventListener('click', () => {
      addToBag(p, 'M');
      toast('Added to bag');
      setTimeout(() => openOverlay('hl-drawer'), 650);
    });
    openOverlay('hl-qv');
  }

  function initQuickView() {
    document.addEventListener('click', (e) => {
      const card = e.target.closest('[data-product]');
      if (card && !e.target.closest('a')) {
        e.preventDefault();
        openQuickView(card.dataset.product);
      }
    });
    $('[data-close="qv"]')?.addEventListener('click', () => closeOverlay('hl-qv'));
  }

  /* ——— Cursor ——— */
  function initCursor() {
    if (REDUCED || !window.matchMedia('(hover: hover)').matches) return;
    const ring = document.createElement('div');
    ring.className = 'hl-cursor';
    const dot = document.createElement('div');
    dot.className = 'hl-cursor-dot';
    const label = document.createElement('div');
    label.className = 'hl-cursor-label';
    document.body.append(ring, dot, label);

    let mx = 0;
    let my = 0;
    let rx = 0;
    let ry = 0;
    document.addEventListener('mousemove', (e) => {
      mx = e.clientX;
      my = e.clientY;
    });
    function tick() {
      rx += (mx - rx) * 0.18;
      ry += (my - ry) * 0.18;
      ring.style.transform = `translate(${rx}px, ${ry}px) translate(-50%, -50%)`;
      dot.style.transform = `translate(${mx}px, ${my}px) translate(-50%, -50%)`;
      label.style.transform = `translate(${mx}px, ${my + 22}px) translate(-50%, -50%)`;
      requestAnimationFrame(tick);
    }
    tick();

    document.addEventListener('mouseover', (e) => {
      const t = e.target.closest('a, button, [data-product], [data-cursor]');
      ring.classList.toggle('is-big', !!t);
      const col = t && getComputedStyle(t).getPropertyValue('--cc').trim();
      if (col) ring.style.borderColor = col;
      const lbl = t && t.getAttribute('data-cursor-label');
      label.textContent = lbl || '';
      label.classList.toggle('is-on', !!lbl);
    });
  }

  /* ——— Magnetic buttons ——— */
  function initMagnetic() {
    if (REDUCED) return;
    $$('.hl-pill, .hl-btn-primary, [data-magnetic]').forEach((btn) => {
      btn.addEventListener('mousemove', (e) => {
        const r = btn.getBoundingClientRect();
        const x = e.clientX - r.left - r.width / 2;
        const y = e.clientY - r.top - r.height / 2;
        btn.style.transform = `translate(${x * 0.12}px, ${y * 0.12}px)`;
      });
      btn.addEventListener('mouseleave', () => {
        btn.style.transform = '';
      });
    });
  }

  /* ——— Lenis + ScrollTrigger ——— */
  function initSmoothScroll() {
    if (typeof Lenis === 'undefined' || typeof gsap === 'undefined') return;
    lenis = new Lenis({ lerp: REDUCED ? 1 : 0.08, smoothWheel: !REDUCED });
    lenis.on('scroll', ScrollTrigger.update);
    gsap.ticker.add((time) => lenis.raf(time * 1000));
    gsap.ticker.lagSmoothing(0);
  }

  /* ——— Reveal helpers ——— */
  function initReveals() {
    if (REDUCED || typeof gsap === 'undefined') {
      $$('[data-lines]').forEach((el) => {
        el.innerHTML = el.textContent;
      });
      return;
    }
    $$('.mask-line').forEach((line) => {
      const inner = line.querySelector('span');
      if (inner) {
        gsap.from(inner, {
          yPercent: 110,
          duration: 1,
          ease: 'power3.out',
          scrollTrigger: { trigger: line, start: 'top 88%' },
        });
      }
    });
    $$('[data-lines]').forEach((el) => {
      const words = el.textContent.trim().split(/\s+/);
      el.innerHTML = words.map((w) => `<span class="w">${w}</span>`).join(' ');
      gsap.to(el.querySelectorAll('.w'), {
        opacity: 1,
        duration: 0.6,
        stagger: 0.03,
        ease: 'power2.out',
        scrollTrigger: { trigger: el, start: 'top 85%' },
      });
    });
    $$('[data-reveal="img"]').forEach((wrap) => {
      gsap.from(wrap, {
        clipPath: 'inset(100% 0 0 0)',
        duration: 1.2,
        ease: 'expo.inOut',
        scrollTrigger: { trigger: wrap, start: 'top 80%' },
      });
      const media = wrap.querySelector('img, video, .hl-media-fallback');
      if (media) {
        gsap.from(media, {
          scale: 1.35,
          duration: 1.4,
          ease: 'power2.out',
          scrollTrigger: { trigger: wrap, start: 'top 80%' },
        });
      }
    });
  }

  /* ——— Loader + Hero (index) ——— */
  function initLoaderHero() {
    const loader = $('#hl-loader');
    const hero = $('.hl-hero');
    if (!hero) return;

    const title = $('.hl-hero-title');
    if (title && !title.dataset.split) {
      title.dataset.split = '1';
      title.querySelectorAll('.hl-hero-line-1, .hl-hero-line-3').forEach((line) => {
        const text = line.textContent;
        line.textContent = '';
        text.split('').forEach((c) => {
          const s = document.createElement('span');
          s.className = 'char';
          s.textContent = c === ' ' ? '\u00a0' : c;
          line.appendChild(s);
        });
      });
    }

    if (REDUCED || !loader || typeof gsap === 'undefined') {
      loader?.remove();
      return;
    }

    if (lenis) lenis.stop();
    const countEl = $('.hl-loader-count');
    const bands = $$('.hl-loader-band');
    const obj = { v: 0 };
    const tl = gsap.timeline({
      onComplete: () => {
        loader.remove();
        if (lenis) lenis.start();
      },
    });

    tl.to(bands, {
      scaleY: 1,
      duration: 0.9,
      stagger: 0.08,
      ease: 'expo.inOut',
      transformOrigin: 'bottom center',
    })
      .to(
        obj,
        {
          v: 100,
          duration: 1.8,
          ease: 'power1.inOut',
          onUpdate: () => {
