        ease: 'expo.out',
      })
      .from(
        '.hl-hero-title .char',
        { yPercent: 115, rotation: 6, opacity: 1, duration: 0.9, stagger: 0.025, ease: 'power3.out' },
        '-=1.1'
      )
      .to('.hl-hero-eyebrow, .hl-hero-foot', { opacity: 1, y: 0, duration: 0.8, ease: 'power2.out' }, '-=0.6');

    const video = $('.hl-hero-media video');
